import static org.junit.jupiter.api.Assertions.*;

public class TextHelpAppendableTest {

    /**
     * Subclass to capture the Queue passed into printQueue when printWrapped is invoked.
     * Overrides the (presumed protected) printQueue method from TextHelpAppendable.
     */
    static class CapturingTextHelpAppendable extends TextHelpAppendable {
        private Queue<String> captured;

        public CapturingTextHelpAppendable(final Appendable out) {
            super(out);
        }

        @Override
        protected void printQueue(final Queue<String> q) throws IOException {
            this.captured = q;
        }

        public Queue<String> getCapturedQueue() {
            return captured;
        }
    }

    @Test
    public void testPrintWrapped_splitsOnSpaces() throws Exception {
        CapturingTextHelpAppendable app = new CapturingTextHelpAppendable(new StringBuilder());

        // Configure the TextStyle builder to force wrapping at small width and no padding/indent.
        TextStyle.Builder builder = app.getTextStyleBuilder();
        builder.setMaxWidth(5).setLeftPad(0).setIndent(0);

        // Invoke the focal method
        app.printWrapped("one two three");

        // Verify the captured queue contains the expected wrapped pieces
        Queue<String> q = app.getCapturedQueue();
        assertNotNull(q, "Captured queue should not be null");
        assertEquals(3, q.size(), "Expected three wrapped segments");

        // Trim to be tolerant of any leftPad/indent behavior
        assertEquals("one", q.poll().trim());
        assertEquals("two", q.poll().trim());
        assertEquals("three", q.poll().trim());
    }

    @Test
    public void testPrintWrapped_emptyProducesNoLines() throws Exception {
        CapturingTextHelpAppendable app = new CapturingTextHelpAppendable(new StringBuilder());

        // Ensure reasonable style
        app.getTextStyleBuilder().setMaxWidth(10).setLeftPad(0).setIndent(0);

        // Empty input should produce an empty queue
        app.printWrapped("");
        Queue<String> q = app.getCapturedQueue();
        assertNotNull(q, "Captured queue should not be null even for empty input");
        assertEquals(0, q.size(), "Empty input should yield zero lines");
    }

    @Test
    public void testMakeColumnQueue_viaReflection() throws Exception {
        CapturingTextHelpAppendable app = new CapturingTextHelpAppendable(new StringBuilder());

        // Make style that forces single-character tokens to become individual lines
